import logging
from datetime import datetime
import xarray as xr
from satpy.readers.file_handlers import BaseFileHandler

logger = logging.getLogger(__name__)

class ViirsL2NCFileHandler(BaseFileHandler):
    """File handler for VIIRS L2 NOAA enterprise data in netCDF format."""

    def __init__(self, filename, filename_info, filetype_info):
        """Initialize the reader."""
        super().__init__(filename, filename_info, filetype_info)
        self.nc = xr.open_dataset(self.filename,
                                  decode_cf=True,
                                  mask_and_scale=False,
                                  chunks={"x": "auto", "y": "auto"})

        self.sensor = "viirs"
        self.platform_name = self.nc.attrs.get("satellite_name", "Unknown")
        self.platform_shortname = filename_info.get("platform", "Unknown")
        self._meta = None

    @property
    def start_time(self):
        """Start timestamp of the dataset."""
        dt = self.nc.attrs.get("time_coverage_start")
        if dt:
            return datetime.strptime(dt, "%Y-%m-%dT%H:%M:%SZ")
        return None

    @property
    def end_time(self):
        """End timestamp of the dataset."""
        dt = self.nc.attrs.get("time_coverage_end")
        if dt:
            return datetime.strptime(dt, "%Y-%m-%dT%H:%M:%SZ")
        return None

    def get_dataset(self, key, info):
        """Load a dataset."""
        var = info["file_key"]
        logger.debug("Reading in get_dataset %s.", var)
        variable = self.nc[var]

        # Data has 'Latitude' and 'Longitude' coords, these must be replaced.
        # Based on the prompt: Rows -> y, Columns -> x
        rename_dict = {}
        if "Rows" in variable.dims:
            rename_dict["Rows"] = "y"
        if "Columns" in variable.dims:
            rename_dict["Columns"] = "x"

        if rename_dict:
            variable = variable.rename(rename_dict)

        if "Latitude" in variable.coords:
            variable = variable.drop_vars("Latitude")
        if "Longitude" in variable.coords:
            variable = variable.drop_vars("Longitude")

        variable.attrs.update(key.to_dict())
        return variable

    def get_area_def(self, dsid):
        """Get the area definition."""
        # For VIIRS L2, we don't have the projection parameters here.
        return None
